package org.humanjourney.core.geography;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import com.google.gson.JsonParser;
import java.util.*;
import net.minecraft.nbt.NbtOps;
import org.humanjourney.core.npc.context.*;
import org.humanjourney.core.npc.economy.EconomyCatalog;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
class GeographyTest {
 final GeographyContext both=new GeographyContext("test_macro","Macro","test_local","Local");final GeographyRoles student=new GeographyRoles(true,true,false),teacher=new GeographyRoles(true,false,true);
 @Test void studentDiscoversMacroAndLocalIndependently(){var d=new DiscoveryLedger();var delta=d.discover(student,both);assertEquals(Set.of("test_macro"),delta.macros());assertEquals(Set.of("test_local"),delta.locals());assertEquals(1,delta.revision());}
 @Test void macroOnlyDoesNotRequireLocalCoverage(){var d=new DiscoveryLedger();assertTrue(d.discover(student,new GeographyContext("test_macro","Macro","","")).changed());assertEquals(Set.of("test_macro"),d.snapshot().macros());assertTrue(d.snapshot().locals().isEmpty());}
 @Test void localOnlyCanBeDiscoveredWithoutMacro(){var d=new DiscoveryLedger();d.discover(student,new GeographyContext("","","test_local","Local"));assertTrue(d.snapshot().macros().isEmpty());assertEquals(Set.of("test_local"),d.snapshot().locals());}
 @Test void reentryAndSecondStudentShareOneLedger(){var d=new DiscoveryLedger();d.discover(student,both);assertFalse(d.discover(new GeographyRoles(true,true,false),both).changed());assertEquals(1,d.snapshot().revision());assertEquals(1,d.snapshot().macros().size());assertEquals(1,d.snapshot().locals().size());}
 @Test void teachersAndConflictingTeacherStudentStateNeverDiscover(){for(var role:List.of(teacher,new GeographyRoles(true,true,true))){var d=new DiscoveryLedger();assertFalse(d.discover(role,both).changed());assertTrue(d.snapshot().macros().isEmpty());assertTrue(d.snapshot().locals().isEmpty());}}
 @Test void nonParticipantsAndParticipantOnlyViewersDoNotDiscover(){for(var role:List.of(new GeographyRoles(false,false,false),new GeographyRoles(false,true,false),new GeographyRoles(true,false,false))){var d=new DiscoveryLedger();assertFalse(d.discover(role,both).changed());}}
 @Test void exactProductionTagsAreUsed(){assertTrue(GeographyRoles.from(Set.of("hj_participant","hj_student")).canDiscover());assertFalse(GeographyRoles.from(Set.of("hj_participant","hj_student","hj_teacher")).canDiscover());assertFalse(GeographyRoles.from(Set.of("participant","student")).participant());}
 @Test void labelsAreNotDiscoveryIdentity(){var d=new DiscoveryLedger();d.discover(student,both);assertFalse(d.discover(student,new GeographyContext("test_macro","New Macro","test_local","New Local")).changed());assertEquals(1,d.snapshot().revision());}
 @Test void nativeSavedDataCodecRoundTripRetainsIndependentAndStaleIds(){var d=new SavedDiscovery();d.mark(DiscoveryLedger.Kind.MACRO,"macro_one");d.mark(DiscoveryLedger.Kind.LOCAL,"removed_local");var encoded=SavedDiscovery.CODEC.encodeStart(NbtOps.INSTANCE,d).getOrThrow();var restored=SavedDiscovery.CODEC.parse(NbtOps.INSTANCE,encoded).getOrThrow();assertEquals(d.snapshot(),restored.snapshot());assertEquals(Set.of("removed_local"),restored.snapshot().locals());assertEquals("human_journey_geography",SavedDiscovery.TYPE.id());}
 @Test void dirtyFlagOnlyChangesForNewDiscoveryAndReset(){var d=new SavedDiscovery();assertFalse(d.isDirty());d.discover(teacher,both);assertFalse(d.isDirty());d.discover(student,both);assertTrue(d.isDirty());d.setDirty(false);d.discover(student,both);assertFalse(d.isDirty());d.reset();assertTrue(d.isDirty());assertTrue(d.snapshot().macros().isEmpty());assertTrue(d.snapshot().locals().isEmpty());}
 @Test void invalidManualIdsRejectWithoutMutation(){var d=new DiscoveryLedger();assertThrows(IllegalArgumentException.class,()->d.mark(DiscoveryLedger.Kind.MACRO,"BAD ID"));assertTrue(d.snapshot().macros().isEmpty());}
 @Test void macroAndLocalHudArePrimaryAndSecondary(){var h=HudPresentation.of(true,both);assertEquals("Local",h.primary());assertEquals("Macro",h.secondary());assertTrue(h.visible());}
 @Test void macroOnlyAndMissingGeographyHud(){assertEquals(new HudPresentation("Macro",""),HudPresentation.of(true,new GeographyContext("test_macro","Macro","","")));assertFalse(HudPresentation.of(true,GeographyContext.EMPTY).visible());assertFalse(HudPresentation.of(false,both).visible());}
 @Test void teacherGetsHudWithoutChangingDiscovery(){var d=new DiscoveryLedger();var client=new ClientGeographyState();client.accept(new GeographyPackets.Context(teacher.participant(),both));d.discover(teacher,both);assertTrue(client.hud().visible());assertEquals("Local",client.hud().primary());assertTrue(d.snapshot().locals().isEmpty());}
 @Test void participantJoinSnapshotThenDeltaAndResetUpdateClient(){var ledger=new DiscoveryLedger();ledger.discover(student,both);var client=new ClientGeographyState();GeographyPackets.snapshot(ledger.snapshot()).forEach(client::accept);assertEquals(ledger.snapshot(),client.discovery());var delta=ledger.mark(DiscoveryLedger.Kind.LOCAL,"second_local");client.accept(new GeographyPackets.Discovery(GeographyPackets.Kind.DELTA,delta.revision(),List.of(),new ArrayList<>(delta.locals())));assertEquals(ledger.snapshot(),client.discovery());ledger.reset();GeographyPackets.snapshot(ledger.snapshot()).forEach(client::accept);assertTrue(client.discovery().locals().isEmpty());}
 @Test void largeSnapshotsPublishAtomicallyAndAreBounded(){var ids=new TreeSet<String>();for(int i=0;i<600;i++)ids.add("local_"+i);var snapshot=new DiscoveryLedger.Snapshot(Set.of("macro"),ids,4);var packets=GeographyPackets.snapshot(snapshot);assertEquals(5,packets.size());var client=new ClientGeographyState();for(int i=0;i<packets.size()-1;i++){assertTrue(packets.get(i).locals().size()<=128);client.accept(packets.get(i));assertTrue(client.discovery().locals().isEmpty());}client.accept(packets.getLast());assertEquals(snapshot,client.discovery());}
 @Test void disconnectAndRoleRemovalClearClientMirror(){var c=new ClientGeographyState();c.accept(new GeographyPackets.Context(true,both));c.accept(new GeographyPackets.Discovery(GeographyPackets.Kind.SINGLE,5,List.of("macro"),List.of("local")));c.clear();assertFalse(c.hud().visible());assertTrue(c.discovery().macros().isEmpty());c.accept(new GeographyPackets.Context(true,both));c.accept(new GeographyPackets.Context(false,GeographyContext.EMPTY));assertFalse(c.hud().visible());}
 @Test void repeatedMovementInOneContextDoesNotRequireContextOrFullStateTraffic(){var t=new GeographySyncTracker();var input=new GeographySyncTracker.Input(1,"minecraft:overworld",1,2,"era_test",1,student);assertTrue(t.joining(input));assertTrue(t.evaluate(input));t.observed(input,both);var packet=new GeographyPackets.Context(true,both);t.sent(packet);t.synced(2);assertFalse(t.joining(input));assertFalse(t.evaluate(input));var moved=new GeographySyncTracker.Input(1,"minecraft:overworld",2,2,"era_test",1,student);assertTrue(t.evaluate(moved));assertFalse(t.contextChanged(packet));assertFalse(t.needsSnapshot(2));}
 @Test void roleRespawnEraAndDataChangesInvalidateEvaluation(){var t=new GeographySyncTracker();var input=new GeographySyncTracker.Input(1,"minecraft:overworld",1,2,"era_test",1,teacher);t.observed(input,both);assertTrue(t.evaluate(new GeographySyncTracker.Input(1,"minecraft:overworld",1,2,"era_test",1,student)));assertTrue(t.joining(new GeographySyncTracker.Input(2,"minecraft:overworld",1,2,"era_test",1,teacher)));assertTrue(t.evaluate(new GeographySyncTracker.Input(1,"minecraft:overworld",1,2,"era_other",1,teacher)));assertTrue(t.evaluate(new GeographySyncTracker.Input(1,"minecraft:overworld",1,2,"era_test",2,teacher)));}
 NpcContextStore.Data data(String macroLabel){var json=JsonParser.parseString("{\"schema_version\":1,\"macro_regions\":[{\"id\":\"test_macro\",\"display_label\":\""+macroLabel+"\",\"era_labels\":{\"era_test\":\"Era Macro\"},\"polygon\":[[0,0],[100,0],[100,100],[0,100]]}],\"local_areas\":[{\"id\":\"test_local\",\"macro_region\":\"test_macro\",\"display_label\":\"Local Label\",\"era_labels\":{\"era_test\":\"Era Local\"},\"polygon\":[[10,10],[20,10],[20,20],[10,20]]}]}");var geo=NpcGeography.parse(List.of(json),Set.of("era_test"));var eras=EraRules.parse(JsonParser.parseString("{\"eras\":[{\"id\":\"era_test\",\"conditions\":[{\"objective\":\"testEra\",\"holder\":\"#era\",\"operator\":\"EQUALS\",\"value\":0}]}]}"));return new NpcContextStore.Data(eras,geo,Map.of(),Map.of(),0,EconomyCatalog.empty());}
 @Test void existingResolverAndEraLabelsFeedHudWithoutChangingNpcNaming(){var data=data("Macro Label");var view=GeographyContext.resolve(data,(o,h)->OptionalInt.of(0),"minecraft:overworld",15,15);assertEquals("Era Local",view.localLabel());assertEquals("Era Macro",view.macroLabel());assertEquals("none",data.geography().resolve("minecraft:overworld",50,50,"era_test").label());assertEquals("test_macro",GeographyContext.resolve(data,(o,h)->OptionalInt.of(0),"minecraft:overworld",50,50).macroId());assertFalse(GeographyContext.resolve(data,(o,h)->OptionalInt.empty(),"minecraft:overworld",200,200).visible());}
 @Test void missingLabelsGetReadablePresentationFallbackWithoutRawIds(){assertEquals("Northern Europe",GeographyContext.readable("northern_europe"));var data=data("");var view=GeographyContext.resolve(data,(o,h)->OptionalInt.empty(),"minecraft:overworld",50,50);assertEquals("Test Macro",view.macroLabel());assertFalse(view.macroLabel().contains("_"));}
 @Test void hudLayoutFitsTextAndUsesCompactTwoLineHeight(){var one=HudPresentation.layout(480,270,100,false,170,10,1);var two=HudPresentation.layout(480,270,140,true,170,10,1);assertEquals(110,one.width());assertEquals(19,one.height());assertEquals(30,two.height());assertEquals(170,two.x());assertTrue(HudPresentation.layout(200,100,140,true,999,999,1).x()+150<=200);}
 ClassNode read(String name)throws Exception{try(var in=getClass().getClassLoader().getResourceAsStream(name+".class")){assertNotNull(in);var c=new ClassNode();new ClassReader(in).accept(c,0);return c;}}
 @Test void commonPathsHaveNoClientClassInstructionsAndUseNativeSavedData()throws Exception{for(String type:List.of("GeographyBootstrap","GeographyServer","GeographyNetwork","SavedDiscovery","GeographyPackets","DiscoveryLedger")){var c=read("org/humanjourney/core/geography/"+type);for(var m:c.methods){assertFalse(m.desc.contains("net/minecraft/client"));for(var i:m.instructions)if(i instanceof MethodInsnNode call)assertFalse(call.owner.startsWith("net/minecraft/client/"));else if(i instanceof FieldInsnNode field)assertFalse(field.owner.startsWith("net/minecraft/client/"));}}assertEquals("net/minecraft/world/level/saveddata/SavedData",read("org/humanjourney/core/geography/SavedDiscovery").superName);}
 @Test void hudUsesCurrentForgeLayerEventAndModernMatrixStack()throws Exception{var c=read("org/humanjourney/core/geography/client/GeographyClient");var calls=new HashSet<String>();for(var m:c.methods)for(var i:m.instructions)if(i instanceof MethodInsnNode call){calls.add(call.owner);assertFalse(call.owner.contains("RegisterGuiOverlaysEvent"));assertFalse(call.owner.contains("RenderGuiOverlayEvent"));}assertTrue(calls.contains("net/minecraftforge/client/event/AddGuiOverlayLayersEvent"));var hud=read("org/humanjourney/core/geography/client/GeographyHud");assertTrue(hud.methods.stream().anyMatch(m->m.name.equals("render")));}
 @Test void transportIsClientboundOnlyAndNeverCarriesPolygons()throws Exception{var c=read("org/humanjourney/core/geography/GeographyNetwork");var calls=new HashSet<String>();for(var m:c.methods)for(var i:m.instructions)if(i instanceof MethodInsnNode call)calls.add(call.name);assertTrue(calls.contains("clientbound"));assertFalse(calls.contains("serverbound"));for(var component:GeographyPackets.Context.class.getRecordComponents())assertFalse(component.getType().getName().contains("NpcGeography"));}
 @Test void adminCommandRejectsUnknownIdAndKeepsExistingHjCommands()throws Exception{var dispatcher=new com.mojang.brigadier.CommandDispatcher<net.minecraft.commands.CommandSourceStack>();var event=new net.minecraftforge.event.RegisterCommandsEvent(dispatcher,net.minecraft.commands.Commands.CommandSelection.ALL,org.mockito.Mockito.mock(net.minecraft.commands.CommandBuildContext.class));org.humanjourney.core.npc.NpcCommands.register(event);GeographyCommands.register(event);var source=org.mockito.Mockito.mock(net.minecraft.commands.CommandSourceStack.class);org.mockito.Mockito.when(source.hasPermission(2)).thenReturn(true);assertEquals(0,dispatcher.execute("hj geography discovery mark macro never_defined_test_id",source));org.mockito.Mockito.verify(source).sendFailure(org.mockito.ArgumentMatchers.any(net.minecraft.network.chat.Component.class));assertNotNull(dispatcher.getRoot().getChild("hj").getChild("npc"));assertFalse(dispatcher.getRoot().getChild("hj").getChild("geography").canUse(org.mockito.Mockito.mock(net.minecraft.commands.CommandSourceStack.class)));}
}
